inline hkVector4 NiPointToHkVector(const NiPoint3& kPt)
{
    hkVector4 kVec;
    kVec.x = kPt.x * 0.1428767293691635;
    kVec.y = kPt.y * 0.1428767293691635;
    kVec.z = kPt.z * 0.1428767293691635;
    return kVec;
}

bhkPickData::bhkPickData() : unkA0(0), m_iCollectorType(0), m_pCollector(0), bUnkAC(false)
{
    m_rayDelta = hkVector4_getZero();
}

void bhkPickData::FUN_00469050(const NiPoint3* pStart)
{
    m_input.m_from = NiPointToHkVector(*pStart);
}

void bhkPickData::FUN_0068daa0(const NiPoint3& kDelta)
{
    m_rayDelta = NiPointToHkVector(kDelta);
}

void bhkPickData::FUN_00469bd0(const NiPoint3* pEnd)
{
    hkVector4 kEnd = NiPointToHkVector(*pEnd);
    m_rayDelta = hkVector4_getZero();
    m_input.m_to = kEnd;
}


